"""
experience-brain-feeder.py — Feed experience-bank rows into ExperienceBrain.

Bridges the gap: experience-bank-append.py writes JSONL rows,
but ExperienceBrain (money-intelligence/experience_layer) never consumes them.

This script reads unprocessed experience-bank rows and:
1. Feeds each as a situation to ExperienceBrain.analyze()
2. Records outcomes for resolved rows via ExperienceBrain.record_outcome()
3. Marks rows as brain-processed to avoid re-processing

Usage:
  python experience-brain-feeder.py [--dry-run]
"""
import json
import sys
import argparse
from pathlib import Path
from datetime import datetime, timezone, timedelta

REPO_ROOT = Path(__file__).parent.parent.parent.parent.parent
EXPERIENCE_BANK_DIR = REPO_ROOT / "data" / "experience-bank"
SAIGON_TZ = timezone(timedelta(hours=7))

sys.path.insert(0, str(REPO_ROOT / ".claude" / "skills" / "business" / "money-intelligence"))

PROCESSED_MARKER_FILE = EXPERIENCE_BANK_DIR / ".brain-processed.json"


def load_processed_ids() -> set:
    if PROCESSED_MARKER_FILE.exists():
        try:
            return set(json.loads(PROCESSED_MARKER_FILE.read_text(encoding="utf-8")))
        except (json.JSONDecodeError, TypeError):
            return set()
    return set()


def save_processed_ids(ids: set):
    PROCESSED_MARKER_FILE.write_text(
        json.dumps(sorted(ids), indent=2, ensure_ascii=False), encoding="utf-8"
    )


def read_all_rows() -> list[dict]:
    rows = []
    for f in sorted(EXPERIENCE_BANK_DIR.glob("*.jsonl")):
        for line in f.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                rows.append(json.loads(line))
            except json.JSONDecodeError:
                continue
    return rows


def main():
